139:  const selected = new Set<PromptFragmentId>(
140:    PRODUCT_BASE_FRAGMENTS[request.projectContext.product.kind],
141:  );
142:
143:  if (request.projectContext.product.kind === "generic_web") {
144:    for (const fragment of selectGenericFallbackFragments(request.packet, request.projectContext)) {
145:      selected.add(fragment);
146:    }
147:  }
148:
149:  const observation: BuilderShadowObservation | undefined =
150:    request.mode === "implement" ? undefined : request.shadowObservation;
151:  if (observation) {
152:    if (observation.failures.some((failure) => failure.category === "locator")) {
153:      selected.add("accessible_web_controls");
154:    }
155:    if (observation.applicationStartupFailed) {
156:      selected.add("delivery_contract");
157:    }
158:  }
159:
160:  return FRAGMENT_ORDER.filter((fragment) => selected.has(fragment));
161:}
