163:function selectGenericFallbackFragments(
164:  packet: WorkPacket,
165:  context: BuilderProjectContext,
166:): PromptFragmentId[] {
167:  const haystack = [
168:    context.product.rootName,
169:    context.product.description,
170:    ...context.ancestors.flatMap((ancestor) => [ancestor.name, ancestor.description]),
171:    ...packet.requirements.flatMap((requirement) => [
172:      requirement.name,
173:      requirement.text,
174:      ...requirement.scenarios,
175:    ]),
176:  ]
177:    .join("\n")
178:    .toLowerCase();
179:
180:  const selected = new Set<PromptFragmentId>();
181:  for (const entry of GENERIC_FALLBACK_LEXICON) {
182:    if (entry.keywords.some((keyword) => haystack.includes(keyword))) {
183:      selected.add(entry.fragment);
184:    }
185:  }
186:  return [...selected];
187:}
