71:    let value = trimmed.slice(separator + 1).trim();
72:    const quoted =
73:      (value.startsWith('"') && value.endsWith('"')) ||
74:      (value.startsWith("'") && value.endsWith("'"));
75:    if (quoted && value.length >= 2) {
76:      value = value.slice(1, -1);
77:    }
78:    values[key] = value;
79:  }
