MOJIBAKE_FRAGMENTS = (
    "閸欏秳缍斿",
    "妫版﹢娼?,
    "娴ｆ粎鐡?,
    "鐎光剝鐓?,
    "閹芥顩?,
    "閸掋倕鍠?,
    "鐠囧瓨妲?,
